oxy_webhelp_navlinks = {"aws_planning_protection-d39536e15787":{"topics":[{"title":"Deployment models for AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">When adding an AWS cloud account to <span class=\"ph\">RSC<\/span>, you can choose between an             <span class=\"ph\">RSC<\/span>-managed model and a self-managed model.<\/p>","href":"saas\/aws_deployment_models_cloud_acc.html","attributes":{"data-id":"aws_deployment_models_cloud_acc"},"menu":{"hasChildren":false},"tocID":"aws_deployment_models_cloud_acc-d39536e15807","topics":[]},{"title":"AWS cloud discovery","shortdesc":"<p class=\"shortdesc\">The cloud discovery feature provides a read-only view of AWS resources in <span class=\"ph\">RSC<\/span>. This feature separates workload discovery from workload protection, so         you can view all the resources that exist before choosing what to protect.<\/p>","href":"saas\/aws_cloud_discovery.html","attributes":{"data-id":"aws_cloud_discovery"},"menu":{"hasChildren":false},"tocID":"aws_cloud_discovery-d39536e15824","next":"aws_cloud_discovery-d39536e15824"},{"title":"Licenses and usage for AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">The license you hold determines which AWS deployment model is available when you add         an AWS cloud account, and the Licenses and Usage page shows how much capacity your         <span class=\"ph\">RSC<\/span>-managed accounts consume.<\/p>","href":"saas\/aws_hosted_license_usage.html","attributes":{"data-id":"aws_hosted_license_usage"},"menu":{"hasChildren":false},"tocID":"aws_hosted_license_usage-d39536e15851","topics":[]},{"title":"RBAC for AWS cloud-native protection","shortdesc":"<p class=\"shortdesc\">Role-based Access Control for AWS cloud-native protection allows for precise access         permissions on AWS workloads, thereby enhancing security.<\/p>","href":"saas\/aws_rbac_cnp.html","attributes":{"data-id":"aws_rbac_cnp"},"menu":{"hasChildren":false},"tocID":"aws_rbac_cnp-d39536e15865","next":"aws_rbac_cnp-d39536e15865"},{"title":"AWS SCP restrictions","shortdesc":"<p class=\"shortdesc\">Service control policies can restrict actions in AWS environments, potentially         obstructing <span class=\"ph\">RSC<\/span> operations such as S3 bucket creation. Understanding and         adjusting these policies ensures <span class=\"ph\">RSC<\/span> functionality while maintaining security         and compliance.<\/p>","href":"saas\/aws_scp_restrictions.html","attributes":{"data-id":"aws_scp_restrictions"},"menu":{"hasChildren":false},"tocID":"aws_scp_restrictions-d39536e15901","topics":[]},{"title":"Required permissions for client-side encryption of archival locations","shortdesc":"<p class=\"shortdesc\">Information about the AWS KMS permissions that <span class=\"ph\">RSC<\/span> requires to create,         manage, and rekey client-side encrypted cloud-native archival locations.<\/p>","href":"saas\/aws_cse_required_permissions.html","attributes":{"data-id":"aws_cse_required_permissions"},"menu":{"hasChildren":false},"tocID":"aws_cse_required_permissions-d39536e15918","topics":[]},{"title":"Support for end-of-life engine versions","shortdesc":"<p class=\"shortdesc\">When an AWS RDS engine version reaches end of standard support, AWS restricts the         snapshot restore operations that <span class=\"ph\">RSC<\/span> relies on for archiving and export.         Learn how <span class=\"ph\">RSC<\/span> continues to protect RDS PostgreSQL and Aurora PostgreSQL         snapshots on deprecated versions, and what actions you can take when a version nears or         reaches end of life.<\/p>","href":"saas\/aws_rds_eol_engine_versions.html","attributes":{"data-id":"aws_rds_eol_engine_versions"},"menu":{"hasChildren":false},"tocID":"aws_rds_eol_engine_versions-d39536e15932","topics":[]}]}};